window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"l84LYHQr4Ec","speaker":"Mohieldin Salim Ahmed Ibrahim","role":"Foreign Minister","country":"Sudan","region":"Middle East","url":"https://www.youtube.com/watch?v=l84LYHQr4Ec","date":"20260928","title":"🇸🇩 Sudan -  Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1106,"words":2380,"counts":{"claims":30,"promises":1,"attacks":6},"topics":[{"topic":"Sudan war","share":0.1846,"seconds":204},{"topic":"UNGA ceremony","share":0.131,"seconds":145},{"topic":"Sudan political transition","share":0.1161,"seconds":128},{"topic":"Sudan humanitarian","share":0.0633,"seconds":70},{"topic":"Sudan militias","share":0.0631,"seconds":70},{"topic":"Palestine","share":0.0587,"seconds":65},{"topic":"Sudan military","share":0.0586,"seconds":65},{"topic":"Sudan diplomacy","share":0.0582,"seconds":64},{"topic":"Sudan sanctions","share":0.0579,"seconds":64},{"topic":"Sudan ceasefire","share":0.0567,"seconds":63},{"topic":"UN reform","share":0.0555,"seconds":61},{"topic":"Sudan education","share":0.0552,"seconds":61},{"topic":"Sudan sovereignty","share":0.0409,"seconds":45}],"timeline":[[3,67,"UNGA ceremony"],[69,149,"UNGA ceremony"],[150,215,"Sudan diplomacy"],[217,281,"Sudan sanctions"],[284,345,"UN reform"],[346,406,"Sudan war"],[407,476,"Sudan war"],[479,539,"Sudan political transition"],[542,605,"Sudan ceasefire"],[606,674,"Sudan political transition"],[676,737,"Sudan education"],[737,812,"Sudan war"],[814,884,"Sudan humanitarian"],[884,954,"Sudan militias"],[955,1020,"Sudan military"],[1022,1087,"Palestine"],[1088,1133,"Sudan sovereignty"]],"stances":{"UNGA ceremony":"Mohieldin Salim Ahmed Ibrahim begins his address by offering congratulations to the newly elected President of the General Assembly.","Sudan diplomacy":"Mohieldin Salim Ahmed Ibrahim states that the host country prevented his participation by failing to issue a required visa and calls for measures to safeguard the headquarters agreement.","Sudan sanctions":"Mohieldin Salim Ahmed Ibrahim argues that coercive sanctions imposed on Sudan have caused significant harm to the country's economy, security, and sovereignty.","UN reform":"Mohieldin Salim Ahmed Ibrahim argues that the current disregard for UN principles threatens the international system and calls for specific reforms to the Security Council and the financial system.","Sudan war":"Mohieldin Salim Ahmed Ibrahim asserts that lasting peace in Sudan requires ending external interference, halting arms flows, and disarming terrorist militias while calling for support for the government's civilian protection efforts.","Sudan political transition":"Mohieldin Salim Ahmed Ibrahim advocates for a comprehensive, nationally owned Sudanese dialogue as the optimal path to resolve the crisis, provided it is free from external interference and coercion.","Sudan ceasefire":"Mohieldin Salim Ahmed Ibrahim argues that peace in Sudan requires addressing root causes and disarming groups rather than just signing agreements.","Sudan education":"Mohieldin Salim Ahmed Ibrahim expresses gratitude for being elected vice chair of the least developed countries group and states Sudan's commitment to advancing its development interests and ensuring a smooth graduation from that category.","Sudan humanitarian":"Mohieldin Salim Ahmed Ibrahim states that Sudan has advanced a national effort to restore stability, maintains cooperation with UN offices, and calls for international solidarity regarding the situation in Darfur.","Sudan militias":"The speaker calls for legal accountability against the Rapid Support Forces and its regional sponsors, while criticizing the Security Council's failure to act.","Sudan military":"The speaker asserts that Sudan's armed forces have fought alongside allies in WWII, are currently under attack through sanctions and embargoes, and have adhered to international humanitarian principles throughout the war.","Palestine":"Mohieldin Salim Ahmed Ibrahim asserts that the Palestinian people must be empowered to establish an independent state with Jerusalem as its capital and that refugees must be allowed to return.","Sudan sovereignty":"Mohieldin Salim Ahmed Ibrahim emphasizes the necessity of respecting international law and refraining from interference in Sudan's internal affairs while conveying greetings to General Abdat Al."},"claims":[{"t":60,"quote":"I wish to congratulate Mr. Khal Rahman on his election as president of the general assembly at its 81st session.","topic":"UNGA ceremony","kind":"fact"},{"t":73,"quote":"I also extend my appreciation and gratitude to Miss Anelena Berbach for her capable stewardship of the previous","topic":"UNGA ceremony","kind":"fact"},{"t":94,"quote":"He has exerted considerable efforts to advance the reform process and to put forward initiatives aimed at making the United Nations more effective, influential, and representative.","topic":"UNGA ceremony","kind":"fact"},{"t":151,"quote":"the host country prevented this by failing to issue the visa required for his excellency to participate in this highlevel segment of the general","topic":"Sudan diplomacy","kind":"fact"},{"t":164,"quote":"this situation persisted despite the efforts undertaken by the secretariat and despite the secretary general's request to the host country to issue the entry visa in accordance with its obligations. under the 1947 headquarters agreement.","topic":"Sudan diplomacy","kind":"fact"},{"t":257,"quote":"Sudan has lived under sanctions imposed pursuant to chapter 7 for more than two decades.","topic":"Sudan sanctions","kind":"fact"},{"t":264,"quote":"These sanctions have negatively affected its economy, security, and territorial integrity.","topic":"Sudan sanctions","kind":"fact"},{"t":284,"quote":"the continued disregard for and violation of the purposes and principles of the UN charter through the use or threat of use of force in international relations and through interference in the internal affairs of states in various forms and through disregard for the established principles of international law threaten confidence in the multiral international system and in the charter of the United Nations itself.","topic":"UN reform","kind":"fact"},{"t":356,"quote":"we reaffirm that comprehensive, lasting, and just peace in Sudan in a manner that ensures the non-recurrence of conflict cannot be achieved without ending persistent external interference, halting the flow of weapons, ammunition, and mercenaries into Sudan, dismantling the terrorist militia, stopping its attacks against civilians, cities, civilian objects, infrastructure, dams, medical centers, and hospitals, disarming this militia, and ensuring that arms remain exclusively in the hands of the state and its established legitimate national institutions.","topic":"Sudan war","kind":"fact"},{"t":399,"quote":"We also call for the poor support for the steady progress being made by the Sudanese government in the protection of civilians and the peace buildingilding process.","topic":"Sudan war","kind":"fact"},{"t":410,"quote":"While the destructive war waged by Dagalo's terrorist militia against the Sudanese people continues, the international community's silence and its failure to take steps to deter the atrocities and violations committed by the rebel militia in Sudan, despite the availability of documented and credible evidence","topic":"Sudan war","kind":"fact"},{"t":542,"quote":"the implementation of the provisions of the Jedha declaration regarding the Sudin armed forces and the rapid support forces, including fundamental obligations under international humanitarian law","topic":"Sudan ceasefire","kind":"fact"},{"t":569,"quote":"past experiences and the wars imposed upon Sudan have taught us that peace is not achieved merely through the signing of peace agreements without addressing the root causes of the crisis","topic":"Sudan ceasefire","kind":"fact"},{"t":606,"quote":"The state has already begun preparations and creating a conducive environment for this dialogue aimed at reaching common ground through free discussion and placing the country on the path towards the most appropriate and inclusive political transition that include that excludes no one except outlaws and traitors.","topic":"Sudan political transition","kind":"fact"},{"t":628,"quote":"This transition should ultimately lead to free and fair elections in which all Sudin participate under international and regional observation, allowing our people to determine who governs them at the conclusion of the democratic","topic":"Sudan political transition","kind":"fact"},{"t":643,"quote":"Sudan has joined the borrowers platform in recognition of the importance of development financing. We are actively participating in its foundational work in preparation for its first session next October.","topic":"Sudan political transition","kind":"fact"},{"t":682,"quote":"electing us as vice chair of the group's international coordinating bureau by consensus","topic":"Sudan education","kind":"fact"},{"t":698,"quote":"Sudan has been among the first countries to join the global alliance for south south and triangular","topic":"Sudan education","kind":"fact"},{"t":747,"quote":"preserving the unity, territorial integrity, and political independence of the state, and preventing the outbreak of another armed rebellion.","topic":"Sudan war","kind":"fact"},{"t":764,"quote":"The Sudin people alone are the makers of that decision and will determine their future without influence or pressure in accordance with the principle of national ownership of peaceuilding affirmed in Security Council resolution 2736.","topic":"Sudan war","kind":"fact"},{"t":820,"quote":"This was embodied in the road map submitted to the security council in December 2025.","topic":"Sudan humanitarian","kind":"fact"},{"t":840,"quote":"We continue to cooperate with the office of the coordination of humanitarian affairs and the office of the special representative of the secretary general for children and armed conflict as well as human rights mechanisms.","topic":"Sudan humanitarian","kind":"fact"},{"t":900,"quote":"These continued violations alone undermine the credibility of any political partnership in the political winged wing of the rapid support forces militia during the remainder of the transition period given its continued and reprehensible complicity.","topic":"Sudan militias","kind":"fact"},{"t":922,"quote":"The Security Council has failed to condemn and identify the sponsors, thereby contributing to the concealment of those atrocities.","topic":"Sudan militias","kind":"fact"},{"t":955,"quote":"Our armed forces have fought alongside the allies during World War II.","topic":"Sudan military","kind":"fact"},{"t":976,"quote":"foreign mercenaries who constitute 60% of its members.","topic":"Sudan military","kind":"number"},{"t":1050,"quote":"The cause of Palestine remains the central issue in the Middle East.","topic":"Palestine","kind":"fact"},{"t":1061,"quote":"refugees must be allowed to return in accordance with the resolutions of international legitimacy.","topic":"Palestine","kind":"fact"},{"t":1088,"quote":"We underscore the importance of respect for international law and the charter of the United Nations and the importance of refraining from interference in the internal affairs of","topic":"Sudan sovereignty","kind":"fact"},{"t":1098,"quote":"allow me to convey to you the greetings of General Abdat Al who is at this moment among his people as they chant in one voice, one army, one people behind their leader","topic":"Sudan sovereignty","kind":"fact"}],"promises":[{"t":688,"quote":"We shall work to advance its development interests and economic recovery and ensure a smooth and secure graduation from this category","topic":"Sudan education","kind":"promise"}],"attacks":[{"t":417,"quote":"the international community's silence and its failure to take steps to deter the atrocities and violations committed by the rebel militia in Sudan","topic":"Sudan war","target":"International Community"},{"t":430,"quote":"its disregard for legitimate calls to designate it as a terrorist organization and its failure to take decisive measures to stem the flow of weapons, material and mercenaries supporting the terrorist militia across our borders","topic":"Sudan war","target":"International Community"},{"t":894,"quote":"militia with considerable support from its regional and external sponsors","topic":"Sudan militias","target":"Regional and External Sponsors"},{"t":938,"quote":"fabricating accusations against the Sudin armed forces supported by regionally funded platforms backed by the militia sponsors that disseminate disinformation baseless allegations and fabricated condemnations aimed at tarnishing the reputation of our professional armed forces","topic":"Sudan militias","target":"Militia Sponsors"},{"t":963,"quote":"efforts to undermine and destroy the armed forces and to impose sanctions on their leaders and expand the Darur arms embargo to encompass all of Sudan.","topic":"Sudan military","target":"Sanctioning Actors"},{"t":1026,"quote":"certain neighboring states that have not merely facilitated the transfer of weapons, equipment, and supplies to the militia through their territories, but have also created battlefronts and enabled repeated attacks launched by militias and mercenaries from within their territories in broad daylight and established hospitals along their borders to treat militia casualties.","topic":"Palestine","target":"Neighboring States"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":"UNGA ceremony","text":"I now give the floor to his excellency Mudin Salim Ahmed Ibraim, Minister for Foreign Affairs of the Sudan. In the name of Allah the most merciful and gracious. Peace and blessings be upon our prophet and his family and his Your Excellency Mr. Kil Rahman, President of the General Assembly at its 81st session. Your Excellency Mr. Antonio Gutes, Secretary General of the United Nations. ladies and gentlemen, esteemed At the outset, I wish to congratulate Mr. Khal Rahman on his election as president of the general assembly at its 81st session."},{"t":69,"topic":"UNGA ceremony","text":"I wish him every success in the discharge of his duties. I also extend my appreciation and gratitude to Miss Anelena Berbach for her capable stewardship of the previous I would be remiss not to express our appreciation to his excellency, Mr. Antonio Guter, Secretary General of the United Nations, for his defense of legitimate causes and his protection of the charter. He has exerted considerable efforts to advance the reform process and to put forward initiatives aimed at making the United Nations more effective, influential, and representative. I stand today before this distinguished assembly under deeply regrettable circumstances that Sudan never wished to witness within an organization founded on the principles of sovereign equality among states, respect for international law and the guarantee of equal participation for all member states. Excellency General Abd Fat Al Borhan, chairman of the Transitional Sovereign Council of the Republic of Sudan, was to stand before you today to address the General Assembly on behalf of the Sudanese people and government."},{"t":150,"topic":"Sudan diplomacy","text":"However, the host country prevented this by failing to issue the visa required for his excellency to participate in this highlevel segment of the general More regrettably still, this situation persisted despite the efforts undertaken by the secretariat and despite the secretary general's request to the host country to issue the entry visa in accordance with its obligations. under the 1947 headquarters agreement. the Republic of Sudan calls upon the Secretary General, the General Assembly, and the Committee on Relations with the host country to take the necessary measures to safeguard the sanctity of the headquarters agreement. Sudan further requests that it this incident be formally documented and examined by the relevant UN mechanisms responsible for the implementation of the headquarters agreement."},{"t":217,"topic":"Sudan sanctions","text":"Mr. President, the need remains urgent for comprehensive, equitable, and expeditious reform of the international system in light of these changes and challenges as well as for political administration through dialogue, respect for international law and the peaceful settlement of disputes. There is also need for refraining from the use or threat of use of international relations and avoiding the imposition of coercive sanctions merely on the basis of political disagreements or the exploitation of these sanctions as instruments to achieve specific political or economic objectives. Sudan has lived under sanctions imposed pursuant to chapter 7 for more than two decades. These sanctions have negatively affected its economy, security, and territorial integrity. They have undermined Sudin sovereignty and status, exacerbated cycles of violence affecting the protection of civilians and vulnerable sectors and hindered national reconciliation."},{"t":284,"topic":"UN reform","text":"the continued disregard for and violation of the purposes and principles of the UN charter through the use or threat of use of force in international relations and through interference in the internal affairs of states in various forms and through disregard for the established principles of international law threaten confidence in the multiral international system and in the charter of the United Nations itself. Hence the need for United Nations reform particularly reform of the security Africa should be represented by two permanent seats and the working methods of the security council should be improved in line with current developments and realities. The international financial system should be reformed so as to ensure equality of opportunity in accessing finance and in implementing the Millennium and Sustainable Development Goals as well as climate action. Mr."},{"t":346,"topic":"Sudan war","text":"President, we in Sudan are a peaceloving nation, but we also seek a just peace. Therefore, from this UN hall, we reaffirm that comprehensive, lasting, and just peace in Sudan in a manner that ensures the non-recurrence of conflict cannot be achieved without ending persistent external interference, halting the flow of weapons, ammunition, and mercenaries into Sudan, dismantling the terrorist militia, stopping its attacks against civilians, cities, civilian objects, infrastructure, dams, medical centers, and hospitals, disarming this militia, and ensuring that arms remain exclusively in the hands of the state and its established legitimate national institutions. We also call for the poor support for the steady progress being made by the Sudanese government in the protection of civilians and the peace buildingilding process."},{"t":407,"topic":"Sudan war","text":"Mr. President, peace and stability in Sudan cannot be discussed. While the destructive war waged by Dagalo's terrorist militia against the Sudanese people continues, the international community's silence and its failure to take steps to deter the atrocities and violations committed by the rebel militia in Sudan, despite the availability of documented and credible evidence and its disregard for legitimate calls to designate it as a terrorist organization and its failure to take decisive measures to stem the flow of weapons, material and mercenaries supporting the terrorist militia across our borders are the factors that prolong the war and the militia's continued aggression. Silence regarding the atrocities committed by the terrorist militia in Sudan is not only shameful, unethical, and complicit. It is a betrayal of the civilian victims of women and girls who have demonstrated unprecedented resilience in enduring suffering beyond and indeed of an entire people."},{"t":479,"topic":"Sudan political transition","text":"Mr. President, &gt;&gt; the call for a comprehensive nationallyowned Sudin Sudin dialogue to achieve peace represents one of the key pillars of peace and the optimal path for resolving the current crisis. However, a conducive [clears throat] environment must be established to ensure its success and the achievement of its intended outcomes. This should be through the following parallel and measurable measures to protect civilians, reduce polarization, deescalate tensions and contain political estrangement among civilian political and military forces. Constructive confidence building measures to provide the dialogue with credibility and legitimacy. the dialogue being conducted through a purely Sudanese will free from external interference and free from bargaining, intimidation and coercion practiced by some parties at these um at present."},{"t":542,"topic":"Sudan ceasefire","text":"the implementation of the provisions of the Jedha declaration regarding the Sudin armed forces and the rapid support forces, including fundamental obligations under international humanitarian law, the facilitation of humanitarian action, [snorts] meeting the needs of civilians and affected persons, and ensuring the safe and voluntary passage of civilians leaving areas of hostilities. Mr. President, past experiences and the wars imposed upon Sudan have taught us that peace is not achieved merely through the signing of peace agreements without addressing the root causes of the crisis and eliminating its underlying drivers thereby preventing its recurrence. Rather, peace is a process requiring patience, determination, and commitment to addressing the root causes of conflict, removing sources of instability, disarming armed groups, restricting arms possession to the state, and building peace."},{"t":606,"topic":"Sudan political transition","text":"The state has already begun preparations and creating a conducive environment for this dialogue aimed at reaching common ground through free discussion and placing the country on the path towards the most appropriate and inclusive political transition that include that excludes no one except outlaws and traitors. This transition should ultimately lead to free and fair elections in which all Sudin participate under international and regional observation, allowing our people to determine who governs them at the conclusion of the democratic Sudan has joined the borrowers platform in recognition of the importance of development financing. We are actively participating in its foundational work in preparation for its first session next October. This is undertaken in support of efforts to implement a road map for debt relief. Sudan also seeks to improve relations with international financial institutions, secure the lifting of its temporary suspension from the international monetary fund and establish development partnerships that will enable it to manage the recovery stage."},{"t":676,"topic":"Sudan education","text":"We wish to express our sincere gratitude to the least developed countries group for the confidence it has placed in us and for electing us as vice chair of the group's international coordinating bureau by consensus. We shall work to advance its development interests and economic recovery and ensure a smooth and secure graduation from this category. In the same spirit, Sudan has been among the first countries to join the global alliance for south south and triangular This reflects our belief in the importance of strengthening solidarity, mutual benefit, and horizontal partnership as an alternative to traditional vertical aid-based We hope that our membership will help leverage the considerable influence of this alliance in preparing the country for the post-war period, including economic recovery and Mr."},{"t":737,"topic":"Sudan war","text":"President, we reaffirm Sudan's openness to any sincere and constructive effort aimed at ending the war imposed on its people, thereby securing peace, preserving the unity, territorial integrity, and political independence of the state, and preventing the outbreak of another armed rebellion. Nevertheless, at the same time, we reiterate our categorical rejection of any attempt to impose solutions, dictates, or external agendas upon our people. The Sudin people alone are the makers of that decision and will determine their future without influence or pressure in accordance with the principle of national ownership of peaceuilding affirmed in Security Council resolution 2736. On this basis, we affirm our readiness to cooperate constructively with initiatives aimed at addressing the root causes of the crisis, ending the unjust aggression against our people, preserving national state institutions and sovereignty, supporting efforts to achieve peace and development, and overcoming current We have supported the efforts of the Secretary General's personal envoy for Sudan and his consultations with neighboring countries and we have responded positively to constructive proposals and initiatives aimed at ending the war of aggression."},{"t":814,"topic":"Sudan humanitarian","text":"We have also advanced a purely Sudin effort to overcome the crisis, restore stability and rebuild the country. This was embodied in the road map submitted to the security council in December 2025. In parallel, Sudan continues its positive cooperation with the United Nations, including the office of the special representative of the secretary general on sexual violence in conflict. We continue to cooperate with the office of the coordination of humanitarian affairs and the office of the special representative of the secretary general for children and armed conflict as well as human rights mechanisms. They have enjoyed support from the government of Sudan, whether through the country office or the designated human rights experts on Sudan. We renew our appreciation for and support of the positions of sisterly and friendly countries that support Sudan's sovereignty, unity, and national We call upon the international community to capitalize on global momentum and show solidarity with Darur following the Daglo militia's takeover of Al Faser and the compelling evidence and testimony presented by the Sultan of the Masalid people to the security council."},{"t":884,"topic":"Sudan militias","text":"We call upon you to advance legal accountability processes for the perpetrators. This is one of the effective avenues for deescalation and for curbing the wave of violations committed by the militia with considerable support from its regional and external sponsors. These continued violations alone undermine the credibility of any political partnership in the political winged wing of the rapid support forces militia during the remainder of the transition period given its continued and reprehensible complicity. The Security Council has failed to condemn and identify the sponsors, thereby contributing to the concealment of those atrocities. These sponsors have also continued to recruit foreign mercenaries and provided political cover for the militia's political wing while fabricating accusations against the Sudin armed forces supported by regionally funded platforms backed by the militia sponsors that disseminate disinformation baseless allegations and fabricated condemnations aimed at tarnishing the reputation of our professional armed forces."},{"t":955,"topic":"Sudan military","text":"Our armed forces have fought alongside the allies during World War II. The response has been efforts to undermine and destroy the armed forces and to impose sanctions on their leaders and expand the Darur arms embargo to encompass all of Sudan. This paves the way for the victory of the militia and the foreign mercenaries who constitute 60% of its members. Throughout this war of aggression, the Sudin armed forces have adhered to the following principles. the protection of civilians in accordance with the approved national plan submitted by Sudan to the security Distinction at all times between combatants and civilians and between civilian objects and military targets. Taking precautionary measures to avoid and minimize incidental harm. Refraining from using civilians as human shields. Refraining from recruiting child refraining from enforced disappearances and the arbitrary detention of civilians and adhering to humanitarian truses."},{"t":1022,"topic":"Palestine","text":"To end the war, pressure must be exerted on the regional sponsors and certain neighboring states that have not merely facilitated the transfer of weapons, equipment, and supplies to the militia through their territories, but have also created battlefronts and enabled repeated attacks launched by militias and mercenaries from within their territories in broad daylight and established hospitals along their borders to treat militia casualties. Mr. President, the cause of Palestine remains the central issue in the Middle East. The Palestinian people must be empowered to exercise their right to self-determination and establish their independent state with Jerusalem as its capital and refugees must be allowed to return in accordance with the resolutions of international legitimacy. Sudan also stresses the importance of stability in the Red Sea, Bab al-Mandab and the Gulf region. given their impact on the wider region. There is a need to end the current situation in a manner that spares the peoples of the region the scourge of war and its consequences. We reaffirm our full support for the countries of the region in preserving their sovereignty, security and stability."},{"t":1088,"topic":"Sudan sovereignty","text":"We underscore the importance of respect for international law and the charter of the United Nations and the importance of refraining from interference in the internal affairs of Before concluding, allow me to convey to you the greetings of General Abdat Al who is at this moment among his people as they chant in one voice, one army, one people behind their leader. Peace and the mercy and blessings of God be upon you all. I thank the Minister for Foreign Affairs of the Sudan."}],"compare":[{"topic":"Sudan","share":0.3265,"mean":0.0056,"rank":1,"others":15},{"topic":"Israel–Palestine","share":0.0676,"mean":0.0523,"rank":55,"others":76},{"topic":"UN & its reform","share":0.0638,"mean":0.2055,"rank":164,"others":170}]};
